import{a as t}from"./index-q1Ohmdmf.js";const c={async getTransactions(a={}){return await t.get("/transactions",{params:a})},async getAll(a={}){return await this.getTransactions(a)},async getSummary(){return await t.get("/transactions/summary")},async getRecent(a=5){return await t.get("/transactions/recent",{params:{limit:a}})},async getById(a){return await t.get(`/transactions/${a}`)},async createTransaction(a){return await t.post("/transactions",a)},async create(a){return await this.createTransaction(a)},async updateTransaction(a,n){return await t.put(`/transactions/${a}`,n)},async update(a,n){return await this.updateTransaction(a,n)},async duplicateTransaction(a){return await t.post(`/transactions/${a}/duplicate`)},async duplicate(a){return await this.duplicateTransaction(a)},async restoreTransaction(a){return await t.post(`/transactions/${a}/restore`)},async restore(a){return await this.restoreTransaction(a)},async deleteTransaction(a,n=!1){return await t.delete(`/transactions/${a}`,{params:{hard:n}})},async deleteAllTransactions(){return await t.delete("/transactions/all")},async bulkDeleteTransactions(a){return await t.delete("/transactions/bulk",{data:{transaction_ids:a}})},async delete(a,n=!1){return await this.deleteTransaction(a,n)},async seedTransactions(){return await t.post("/transactions/seed")},async previewCsvImport(a){return await t.post("/transactions/import-csv/preview",a,{headers:{"Content-Type":"multipart/form-data"}})},async confirmCsvImport(a){return await t.post("/transactions/import-csv/confirm",a)},async downloadSampleCsv(){try{const n=await(await fetch("http://127.0.0.1:8000/api/v1/transactions/import-csv/sample")).blob(),s=window.URL.createObjectURL(n),e=document.createElement("a");e.href=s,e.download="sample_transactions.csv",document.body.appendChild(e),e.click(),window.URL.revokeObjectURL(s),document.body.removeChild(e)}catch(a){console.error("Failed to download sample CSV:",a)}}};export{c as t};
